NAV_JS = "<script>\n(function(){\n  // Smart language toggle — sets preference and routes to ES version if available\n  function getLangToggleHref(){\n    var path = window.location.pathname;\n    // Pages that have Spanish equivalents (will grow as we build /es/ pages)\n    var esPages = {\n      '/': '/es/',\n      '/get-quote/': '/get-quote/?lang=es',\n    };\n    // Check if current path has an explicit ES mapping\n    if(esPages[path]) return esPages[path];\n    // If already on an ES page, go back to EN\n    if(path.startsWith('/es/')) return path.replace('/es/','/' );\n    // Default: go to Spanish AI intake\n    return '/get-quote/?lang=es';\n  }\n  // Update all lang toggle links dynamically\n  document.addEventListener('DOMContentLoaded', function(){\n    var href = getLangToggleHref();\n    document.querySelectorAll('.nav-es, .drawer-es, [data-lang-toggle]').forEach(function(el){\n      el.setAttribute('href', href);\n    });\n    // Store language preference\n    document.querySelectorAll('.nav-es, .drawer-es, [data-lang-toggle]').forEach(function(el){\n      el.addEventListener('click', function(){\n        localStorage.setItem('nb_lang', 'es');\n      });\n    });\n    // Restore language preference on load\n    if(localStorage.getItem('nb_lang') === 'es' && !window.location.pathname.startsWith('/es/') && !window.location.search.includes('lang=es')){\n      // User prefers Spanish but is on an EN page — show a subtle indicator\n      document.querySelectorAll('.nav-es, .drawer-es').forEach(function(el){\n        el.style.fontWeight = '700';\n        el.style.opacity = '1';\n      });\n    }\n  });\n})();\n</script>"

def build(slug, title, meta, body, pub_date):
    t = (title or '').replace('<','&lt;').replace('>','&gt;')
    m = (meta or '').replace('"','&quot;')[:160]
    url = 'https://www.nexabuilder.com/blog/' + slug + '/'
    ld = ('{"@context":"https://schema.org","@type":"Article",'
          '"headline":"' + t.replace('"','&quot;') + '",'
          '"url":"' + url + '",'
          '"datePublished":"' + str(pub_date or '2026') + '",'
          '"publisher":{"@type":"Organization","name":"NexaBuilder","url":"https://www.nexabuilder.com"}}')
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{t} | NexaBuilder</title>
<meta name="description" content="{m}">
<link rel="canonical" href="{url}">
{FONT_TAGS}
<script type="application/ld+json">{ld}</script>
<style>{SHARED_CSS}{ARTICLE_CSS}</style>
</head>
<body>
{NAV_HTML}
{DRAWER_HTML}
{CBAR}
<main id="main">
  <div class="article-wrap">
    <nav class="article-breadcrumb" aria-label="Breadcrumb">
      <a href="/">Home</a> &rsaquo; <a href="/blog/">Blog</a> &rsaquo; {t}
    </nav>
    <article class="article-body">{body or ''}</article>
    <div class="article-cta">
      <h3>Ready to start your project?</h3>
      <p>Get matched with CSLB-verified contractors in your area within 48 hours.</p>
      <a href="/get-quote/">Get Free Contractor Quotes &rarr;</a>
    </div>
  </div>
</main>
{FOOTER_HTML}
{NAV_JS}
</body></html>"""

conn = psycopg2.connect(**DB)
cur = conn.cursor()
cur.execute("SELECT slug,title,meta_description,body_html,completed_at::date FROM ai_generated_articles WHERE status='PUBLISHED' AND slug IS NOT NULL ORDER BY completed_at DESC")
rows = cur.fetchall()
conn.close()
print(f'Found {len(rows)} published articles')

s3 = boto3.client('s3', region_name=REGION)
n = 0
for slug, title, meta, body, pub_date in rows:
    if not slug or not body:
        print(f'  SKIP {slug}')
        continue
    html = build(slug, title, meta, body, pub_date)
    s3.put_object(Bucket=BUCKET, Key=f'blog/{slug}/index.html',
                  Body=html.encode('utf-8'), ContentType='text/html', CacheControl='max-age=3600')
    n += 1
    print(f'  OK /blog/{slug}/ ({len(html):,} chars)')
print(f'Done: {n} pages deployed')